export function installSectorSave({getDocument,status}){
 const button=document.createElement('button');button.id='save-sector-variant';button.textContent='Save as new sector variant';document.querySelector('.remote-view').append(button);
 const dialog=document.createElement('dialog');dialog.id='sector-save-dialog';dialog.innerHTML='<form method="dialog"><h2>Save a new sector variant</h2><p id="sector-save-location"></p><label>Variant name<input id="sector-variant-name" required pattern="[a-z0-9][a-z0-9-]{0,119}" placeholder="town-west-market"></label><label>Progress<select id="sector-variant-status"><option value="in-progress">In progress</option><option value="authored">Ready for review</option></select></label><p>Readiness is an authoring label. Campaign compatibility still requires review. Existing variants are never overwritten.</p><p id="sector-save-result" role="status"></p><button type="button" id="sector-save-submit">Save variant</button><button>Close</button></form>';document.body.append(dialog);const $=id=>document.getElementById(id);let token=null,id=null;
 button.onclick=async()=>{const d=getDocument(),params=new URLSearchParams(location.search);id=d?.map.sectorTemplate?.id||params.get('sectorTemplate');if(!d||d.block||!id)return status('Open a sector configuration from the map library before saving a variant.');const t=d.map.sectorTemplate?.transform;if(t&&(t.turns||t.mirror)||Number(params.get('orientation')||0)!==0)return status('Open this configuration at 0° to save a variant with matching entrances.');dialog.showModal();$('sector-save-location').textContent='Configuration: '+id;$('sector-save-result').textContent='Connecting to the local authoring workspace…';$('sector-save-submit').disabled=true;try{const r=await fetch('/api/sector-authoring');if(!r.ok)throw Error();const data=await r.json();if(!data.token)throw Error();token=data.token;$('sector-save-result').textContent='Saves to AnimalFactory3D/sectors and updates the map library.';$('sector-save-submit').disabled=false;}catch{$('sector-save-result').textContent='Direct folder saving is available with npm run serve:workspace. On published pages, use Export JSON instead.';}};
 $('sector-save-submit').onclick=async()=>{if(!$('sector-variant-name').reportValidity())return;const submit=$('sector-save-submit');submit.disabled=true;try{const r=await fetch('/api/sector-authoring/variants',{method:'POST',headers:{'Content-Type':'application/json','X-Sector-Token':token},body:JSON.stringify({id,name:$('sector-variant-name').value,status:$('sector-variant-status').value,map:JSON.parse(getDocument().export())})});const result=await r.json();if(!r.ok)throw Error(result.error);$('sector-save-result').textContent='Saved: '+result.path;status('Sector variant saved. Refresh the map library to see it.');}catch(e){$('sector-save-result').textContent=e.message;}finally{submit.disabled=false;}};
}
